values ('96b09176-62c7-5c32-a7f8-df9147b545c8', 'de', 'Founder Bundle II', null, '<p data-start="0" data-end="49"><strong data-start="0" data-end="49">Das provibe Bundle für echte Geschmacksträger</strong></p>
